namespace EnglishCenter.Api.Infrastructure.Classes;
using System.Text.Json;
using System.Text.Json.Nodes;
using EnglishCenter.Api.Common.Errors;
using EnglishCenter.Api.Common.Replay;
using EnglishCenter.Api.Common.Security;
using EnglishCenter.Api.Common.Time;
using EnglishCenter.Api.Infrastructure.Enrollment;
using EnglishCenter.Api.Infrastructure.Replay;
using EnglishCenter.Api.Services.Academics;
using EnglishCenter.Api.Services.Classes;
using EnglishCenter.Api.Services.Enrollment;
using EnglishCenter.Api.Services.Replay;
using Microsoft.EntityFrameworkCore;
public sealed partial class SqlClassExecutor(Func<EnglishCenterDbContext> factory,BusinessClock clock,int sqlSeconds,int lockMs,int weeklyBudget=10000)
{
    private readonly SqlEnrollmentTransactions tx=new(factory,clock,sqlSeconds,lockMs);
    private DateTime Now=>clock.GetUtcNow().UtcDateTime;
    public async Task<JsonObject> Search(VerifiedSessionToken token,IQueryCollection q,string role,CancellationToken ct)
    {
        var result=await tx.Read(token,role,(db,c)=>SqlClassReads.ClassPage(db,q,role,token.AccountId,c),ct);
        if(role!="AcademicAffairs")await tx.Write(async(s,c)=>{var live=await EnrollmentAuthority.RequireAsync(new SqlEnrollmentRepository(s),token,clock,role,c);await ScopeMany(s.Context,result["items"]!.AsArray().Select(row=>row!["id"]!.GetValue<int>()).ToArray(),role,token.AccountId,c);if(!clock.IsBefore(live.EffectiveDeadline))throw new ApiErrorException(ApiErrorCode.AUTHENTICATION_REQUIRED);return true;},ct);
        return result;
    }
    private static async Task ScopeMany(EnglishCenterDbContext db,int[] ids,string role,int account,CancellationToken ct)
    {var count=await db.Classes.CountAsync(x=>ids.Contains(x.ClassId)&&(role!="Teacher"||x.TeacherId==account)&&(role!="Student"||db.StudentClassAssignments.Any(a=>a.ClassId==x.ClassId&&a.Registration!.Student!.AccountId==account)),ct);if(count!=ids.Distinct().Count())throw new ApiErrorException(ApiErrorCode.NOT_FOUND);}
    private static async Task Scope(EnglishCenterDbContext db,int id,string role,int account,CancellationToken ct)
    {if(!await db.Classes.AnyAsync(x=>x.ClassId==id&&(role!="Teacher"||x.TeacherId==account)&&(role!="Student"||db.StudentClassAssignments.Any(a=>a.ClassId==id&&a.Registration!.Student!.AccountId==account)),ct))throw new ApiErrorException(ApiErrorCode.NOT_FOUND);}
    private async Task<T> ScopedRead<T>(VerifiedSessionToken token,int id,string role,Func<EnglishCenterDbContext,CancellationToken,Task<T>> work,CancellationToken ct)
    {var result=await tx.Read(token,role,async(db,c)=>{await Scope(db,id,role,token.AccountId,c);return await work(db,c);},ct);await tx.Write(async(s,c)=>{var live=await EnrollmentAuthority.RequireAsync(new SqlEnrollmentRepository(s),token,clock,role,c);await Scope(s.Context,id,role,token.AccountId,c);if(!clock.IsBefore(live.EffectiveDeadline))throw new ApiErrorException(ApiErrorCode.AUTHENTICATION_REQUIRED);return true;},ct);return result;}
    public Task<JsonObject> Detail(VerifiedSessionToken token,int id,string role,CancellationToken ct)=>ScopedRead(token,id,role,async(db,c)=>
    {
        var s=await SqlClassRepository.ReadState(db,id,c);var d=ClassWire.Detail(s,Now);if(role=="Teacher"){foreach(var k in new[]{"version","guardContext","allowedActions","disabledReasons"})d.Remove(k);}if(role=="Student"){foreach(var k in new[]{"maxSize","placedCount","createdAt","version","prerequisites","guardContext","allowedActions","disabledReasons"})d.Remove(k);d["teacher"]=new JsonObject{["displayName"]=s.Teacher.FullName};var a=await db.StudentClassAssignments.AsNoTracking().SingleAsync(x=>x.ClassId==id&&x.Registration!.Student!.AccountId==token.AccountId,c);d["assignment"]=ClassWire.Object(new{classAssignmentId=a.ClassAssignmentId,registrationId=a.RegistrationId,assignedAt=ClassWire.At(a.AssignedAt)});}return d;
    },ct);
    public Task<JsonObject> Roster(VerifiedSessionToken token,int id,ClassContactFilter filter,string role,CancellationToken ct)=>ScopedRead(token,id,role,(db,c)=>SqlClassReads.Roster(db,id,filter,role=="Teacher",c),ct);
    public Task<JsonObject> CandidateSearch(VerifiedSessionToken t,ClassContactFilter f,CancellationToken ct)=>tx.Read(t,"AcademicAffairs",(db,c)=>SqlClassReads.CandidatePage(db,f,c),ct);
    public Task<JsonObject> Candidate(VerifiedSessionToken t,int id,CancellationToken ct)=>tx.Read(t,"AcademicAffairs",async(db,c)=>ClassPreviews.Candidate(await SqlClassRepository.Candidate(db,id,true,c),true),ct);
    public Task<JsonObject> Options(VerifiedSessionToken t,int id,IQueryCollection query,CancellationToken ct)
    {var q=new AcademicQuery(query,"page","pageSize","sort");var page=q.Number("page");var size=q.Number("pageSize",20,100);var sort=q.Choice("sort","CODE_ASC","CODE_ASC","CODE_DESC");return tx.Read(t,"AcademicAffairs",async(db,c)=>{var source=await SqlClassRepository.Candidate(db,id,true,c);var rows=db.Classes.AsNoTracking().Where(x=>x.Status=="OPEN"&&x.Program!.CourseId==source.Registration.CourseId&&x.Program.BandId==source.BandAssignment.BandId&&db.StudentClassAssignments.Count(a=>a.ClassId==x.ClassId)<x.MaxSize);var count=await rows.LongCountAsync(c);var sorted=sort=="CODE_ASC"?rows.OrderBy(x=>x.ClassCode).ThenBy(x=>x.ClassId):rows.OrderByDescending(x=>x.ClassCode).ThenByDescending(x=>x.ClassId);var offset=(long)(page-1)*size;var ids=offset>int.MaxValue?[]:await sorted.Skip((int)offset).Take(size).Select(x=>x.ClassId).ToArrayAsync(c);var states=await SqlClassStateReads.Read(db,ids,c);var studentData=await SqlClassTimetable.Students(db,[source.Registration.StudentId],Now,c);var allWindows=states.Values.SelectMany(SqlClassPreviewQueries.Windows).ToArray();var resourceData=await SqlClassTimetable.ResourceSnapshot(db,ids,allWindows,states.Values.Select(x=>x.Class.TeacherId).Distinct().ToArray(),c);var items=new List<JsonObject>();foreach(var key in ids){var state=states[key];var windows=SqlClassPreviewQueries.Windows(state);var preview=ClassPreviews.Placement(state,source,Now,SqlClassTimetable.Student(studentData,source.Registration.StudentId,windows),SqlClassTimetable.Resources(resourceData,state,windows,state.Class.TeacherId,true),false);foreach(var field in new[]{"candidate","manifest"})preview.Remove(field);items.Add(preview);}return SqlClassReads.Page(items,page,size,count);},ct);}
    public Task<JsonObject> Preview(VerifiedSessionToken t,int id,string kind,string json,CancellationToken ct)=>tx.Read(t,"AcademicAffairs",async(db,c)=>
    {
        var s=await SqlClassRepository.ReadState(db,id,c);using var doc=JsonDocument.Parse(json);var b=doc.RootElement;
        if(kind=="schedule")return await SqlClassPreviewQueries.Schedule(db,s,ScheduleCandidate.Parse(Single(b,"candidate")),Now,c);
        if(kind=="teacher")return await SqlClassPreviewQueries.Teacher(db,s,Id(Single(b,"teacherId")),Now,c);
        if(kind=="placement")return await SqlClassPreviewQueries.Placement(db,s,await SqlClassRepository.Candidate(db,Id(Single(b,"registrationId")),true,c),Now,c);
        var action=Single(b,"action");if(action.ValueKind!=JsonValueKind.String||action.GetString() is not("OPEN" or "CANCEL" or "START" or "COMPLETE"))throw ApiErrorException.Validation("action");return await SqlClassPreviewQueries.Transition(db,s,action.GetString()!,Now,c);
    },ct);
    public static JsonElement Single(JsonElement b,string key){if(b.ValueKind!=JsonValueKind.Object||b.EnumerateObject().Count()!=1||!b.TryGetProperty(key,out var v))throw ApiErrorException.Validation();return v;}
    public static int Id(JsonElement v){try{return EnglishCenter.Api.Common.Serialization.StrictScalars.ParseInt32(v,1,int.MaxValue);}catch(ArgumentException){throw ApiErrorException.Validation();}}
    public Task<JsonObject> TeacherOptions(VerifiedSessionToken t,IQueryCollection query,CancellationToken ct)
    {var q=new AcademicQuery(query,"classId");var id=q.Id("classId");return tx.Read(t,"AcademicAffairs",async(db,c)=>{ClassState? state=id is { } key?await SqlClassRepository.ReadState(db,key,c):null;var teachers=await db.Accounts.AsNoTracking().Where(x=>db.Roles.Any(r=>r.RoleId==x.RoleId&&r.RoleCode=="Teacher")).OrderBy(x=>x.FullName).ThenBy(x=>x.AccountId).ToArrayAsync(c);var resourceData=state is null?new ResourceData([],[]):await SqlClassTimetable.ResourceSnapshot(db,[state.Class.ClassId],SqlClassPreviewQueries.Windows(state),teachers.Select(x=>x.AccountId).ToArray(),c);var items=new List<JsonObject>();foreach(var a in teachers){var eligible=a.Status=="ACTIVE";if(state is not null){var preview=ClassPreviews.Teacher(state,a,Now,SqlClassTimetable.Resources(resourceData,state,SqlClassPreviewQueries.Windows(state),a.AccountId,true));eligible=preview["eligible"]!.GetValue<bool>();}var row=ClassWire.Teacher(a);row["version"]=ClassWire.Rv(a.RowVersion);row["eligible"]=eligible;row["blockedReasons"]=eligible?new JsonArray():new JsonArray("Nguồn lực hoặc cửa sổ đổi giáo viên chưa hợp lệ.");items.Add(row);}return ClassWire.Object(new{items,currentTeacherId=state?.Class.TeacherId});},ct);}
    public async Task<ClassCommandOutcome> Command(VerifiedSessionToken token,int api,int id,Guid request,string json,int bytes,CancellationToken ct)
    {await tx.Read(token,"AcademicAffairs",async(db,c)=>{if(api!=92)await Scope(db,id,"AcademicAffairs",token.AccountId,c);return true;},ct);var input=new ClassInput(api,id,request,json,bytes);return await tx.Write((s,c)=>new ClassService(new(s),new SqlReplayRepository(s,lockMs),clock).Command(token,input,c),ct);}
    public Task<SafeCommandCompletion> Lookup(VerifiedSessionToken token,string action,Guid request,CancellationToken ct)=>tx.Write(async(s,c)=>
    {CanonicalAction selected;try{selected=CanonicalActionRegistry.ForCode(action);}catch(ArgumentException){throw ApiErrorException.Validation("action");}if(selected.ApiId is not(92 or 94 or 97 or 99 or 102 or 108 or 118 or 120 or 122 or 124))throw ApiErrorException.Validation("action");var markers=new SqlReplayRepository(s,lockMs);await markers.AcquireAsync(ReplayService.RequestResource(token.AccountId,selected,request),c);var repo=new SqlClassRepository(s);await repo.PrepareAccountsAsync(token,[],c);await AcademicAuthority.RequireAsync(repo,token,clock,c);var result=await new ReplayService(markers,clock).LookupAsync(90,"AcademicAffairs",token.AccountId,action,request,(stored,cancel)=>SqlClassRepository.Matches(s.Context,stored.Target,cancel),c);var live=await AcademicAuthority.RequireAsync(repo,token,clock,c);if(!clock.IsBefore(live.EffectiveDeadline))throw new ApiErrorException(ApiErrorCode.AUTHENTICATION_REQUIRED);return result;},ct);
    public Task<JsonObject> Scheduling(VerifiedSessionToken t,int id,CancellationToken ct)=>tx.Read(t,"AcademicAffairs",async(db,c)=>ClassPreviews.SchedulingContext(await SqlClassRepository.ReadState(db,id,c)),ct);
    public Task<JsonObject> ScheduleDetail(VerifiedSessionToken t,int id,CancellationToken ct)=>tx.Read(t,"AcademicAffairs",(db,c)=>SqlClassReads.ScheduleDetail(db,id,Now,c),ct);
    public Task<JsonObject> Calendar(VerifiedSessionToken t,IQueryCollection query,CancellationToken ct)
    {
        var q=new AcademicQuery(query,"fromDate","toDate","classId","courseId","teacherId","view","sort","page","pageSize");var from=q.Date("fromDate");var to=q.Date("toDate");if(from>to)throw ApiErrorException.Validation("toDate");if(from is null&&to is null){var today=clock.GetToday();from=today.AddDays(-((int)today.DayOfWeek+6)%7);to=from.Value.AddDays(6);}var view=q.Choice("view","current","current","history");var sort=q.Choice("sort","START_ASC","START_ASC","START_DESC");var id=q.Id("classId");var course=q.Id("courseId");var teacher=q.Id("teacherId");var page=q.Number("page");var size=q.Number("pageSize",20,100);
        return tx.Read(t,"AcademicAffairs",async(db,c)=>{var rows=db.Schedules.AsNoTracking();if(view=="current"){var liveIds=db.Database.SqlQuery<int>($"SELECT scheduleId AS Value FROM dbo.vw_CurrentScheduleOccurrences");rows=rows.Where(x=>liveIds.Contains(x.ScheduleId)&&(x.Class!.Status=="PLANNED"||x.Class.Status=="OPEN"||x.Class.Status=="ONGOING"));}if(from is { } f)rows=rows.Where(x=>x.SessionDate>=f);if(to is { } end)rows=rows.Where(x=>x.SessionDate<=end);if(id is { } target)rows=rows.Where(x=>x.ClassId==target);if(course is { } cid)rows=rows.Where(x=>x.Class!.Program!.CourseId==cid);if(teacher is { } tid)rows=rows.Where(x=>x.Class!.TeacherId==tid);var count=await rows.LongCountAsync(c);var sorted=sort=="START_ASC"?rows.OrderBy(x=>x.SessionDate).ThenBy(x=>x.StartTime).ThenBy(x=>x.ScheduleId):rows.OrderByDescending(x=>x.SessionDate).ThenByDescending(x=>x.StartTime).ThenByDescending(x=>x.ScheduleId);var offset=(long)(page-1)*size;var data=offset>int.MaxValue?[]:await sorted.Skip((int)offset).Take(size).ToArrayAsync(c);var states=await SqlClassStateReads.Read(db,data.Select(x=>x.ClassId).Distinct().ToArray(),c);var result=SqlClassReads.Page(data.Select(x=>SqlClassReads.ScheduleView(states[x.ClassId],x)),page,size,count);result["dateWindow"]=ClassWire.Object(new{fromDate=from?.ToString("yyyy-MM-dd"),toDate=to?.ToString("yyyy-MM-dd")});return result;},ct);
    }
}
